components-block-tabs-tabs--tabs-default.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlTabsComponent } from '@domg-wc/components/block';

// VlTabsComponent registreert ook vl-tabs-pane, vl-tab en vl-tab-section.
registerWebComponents([VlTabsComponent]);

const tabs = document.querySelector('vl-tabs');

// change en vl-click komen van de vl-tab in de shadow DOM van vl-tabs en bubbelen niet: luister op vl-tabs zelf.
// event.detail.activeTab is het id van de vl-tabs-pane.
// change volgt op een klik op een tab die niet actief is.
tabs.addEventListener('change', (event) => {
    console.log('change', event.detail.activeTab);
});
// vl-click volgt op een klik op een tab, maar enkel als screenX en screenY van de klik niet 0 zijn: niet bij de
// klik waarmee vl-tabs zelf de tab van active-tab activeert.
tabs.addEventListener('vl-click', (event) => {
    console.log('vl-click', event.detail.activeTab);
});

