components-block-tabs-tabs--tabs-dynamic.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlTabsComponent } from '@domg-wc/components/block';

registerWebComponents([VlTabsComponent, VlButtonComponent]);

let index = 0;

// vl-tabs volgt zijn kinderen met een MutationObserver: een vl-tabs-pane die je toevoegt, krijgt meteen een tab;
// een vl-tabs-pane die je verwijdert, verliest die.
const addPane = () => {
    const div = document.createElement('div');
    div.innerHTML =
        '<vl-tabs-pane id="fiets-' + index + '" title="Fiets ' + index + '">TEST ' + index + '</vl-tabs-pane>';

    if (div.firstElementChild) {
        document.querySelector('vl-tabs#tabs')?.appendChild(div.firstElementChild);
        index++;
    }
};

document.querySelector('#add-pane-button').addEventListener('click', addPane);

// change bubbelt niet: luister op vl-tabs zelf. event.detail.activeTab is het id van de vl-tabs-pane.
document.querySelector('vl-tabs#tabs').addEventListener('change', (event) => {
    console.log('change', event.detail.activeTab);
});
